    service,
    lastConnectionStore,
    AgentConfig(
      providerKind: 'chatgpt-codex',
      modelId: provider.modelId,
      baseUrl: chatGptCodexBaseUrl,
      apiKey: [REDACTED:Sensitive Value],
    ),
  );
  return true;
}

