+      final codemie = resolveProviderAuthSurface(
+        provider: ProviderAuthId.codemie,
+        isMacOS: macos,
+        isIOS: ios,
+        isWeb: web,
+      );
+      expect(chatgpt.primary, codemie.primary, reason: 'macos=$macos');
+      expect(chatgpt.webViewFallback, codemie.webViewFallback);
+    }
+  });
