+          provider: provider,
+          isMacOS: false,
+          isIOS: false,
+          isWeb: true,
+        );
+        expect(surface.primary, ProviderAuthSurfaceKind.embeddedWebView);
+        expect(surface.webViewFallback, isFalse);
+      });
+
+      test('desktop-others → embedded WebView (degraded, notice applies)', () {
