  // a macOS host) — the two must stay mutually exclusive.
  final isIos = iosFn?.call() ?? Platform.isIOS;
  final surface = resolveProviderAuthSurface(
    provider: ProviderAuthId.chatgpt,
    isMacOS: !isIos && Platform.isMacOS,
    isIOS: isIos,
    isWeb: kIsWeb,
