    return extensionCookieCodeMieSignin(
      context: context,
      registry: registry,
      service: service,
      lastConnectionStore: lastConnectionStore,
      orgUrl: orgUrl,
    );
  }
  if (context.mounted) {
    showFahErrorSnack(
